#include "stdlib/blas/ext/base/dmskrev.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/stride2offset.h"
#include <stdint.h>

/**
* Reverses a double-precision floating-point strided array in-place according to a mask.
*
* @param N           number of indexed elements
* @param X           input array
* @param strideX     stride length for X
* @param Mask        mask array
* @param strideMask  stride length for Mask
*/
void API_SUFFIX(stdlib_strided_dmskrev)( const CBLAS_INT N, double *X, const CBLAS_INT strideX, const uint8_t *Mask, const CBLAS_INT strideMask ) {
	const CBLAS_INT ox = stdlib_strided_stride2offset( N, strideX );
	const CBLAS_INT om = stdlib_strided_stride2offset( N, strideMask );
	API_SUFFIX(stdlib_strided_dmskrev_ndarray)( N, X, strideX, ox, Mask, strideMask, om );
}

/**
* Reverses a double-precision floating-point strided array in-place according to a mask and using alternative indexing semantics.
*
* @param N           number of indexed elements
* @param X           input array
* @param strideX     stride length for X
* @param offsetX     starting index for X
* @param Mask        mask array
* @param strideMask  stride length for Mask
* @param offsetMask  starting index for Mask
*/
void API_SUFFIX(stdlib_strided_dmskrev_ndarray)( const CBLAS_INT N, double *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, const uint8_t *Mask, const CBLAS_INT strideMask, const CBLAS_INT offsetMask ) {
	CBLAS_INT ix;
	CBLAS_INT iy;
	CBLAS_INT im;
	CBLAS_INT jm;
	CBLAS_INT m;
	CBLAS_INT n;
	CBLAS_INT i;
	double tmp;

	if ( N <= 0 ) {
		return;
	}
	n = N / 2;
	ix = offsetX;
	im = offsetMask;

	// Use loop unrolling if the strides are equal to `1`...
	if ( strideX == 1 && strideMask == 1 ) {
		m = n % 3;
		iy = ix + N - 1;
		jm = im + N - 1;

		// If we have a remainder, run a clean-up loop...
		if ( m > 0 ) {
			for ( i = 0; i < m; i++ ) {
				if ( Mask[ im ] == 0 && Mask[ jm ] == 0 ) {
					tmp = X[ ix ];
					X[ ix ] = X[ iy ];
					X[ iy ] = tmp;
				}
				ix += 1;
				im += 1;
				iy -= 1;
				jm -= 1;
			}
		}
		if ( n < 3 ) {
			return;
		}
		for ( i = m; i < n; i += 3 ) {
			if ( Mask[ im ] == 0 && Mask[ jm ] == 0 ) {
				tmp = X[ ix ];
				X[ ix ] = X[ iy ];
				X[ iy ] = tmp;
			}
			if ( Mask[ im+1 ] == 0 && Mask[ jm-1 ] == 0 ) {
				tmp = X[ ix+1 ];
				X[ ix+1 ] = X[ iy-1 ];
				X[ iy-1 ] = tmp;
			}
			if ( Mask[ im+2 ] == 0 && Mask[ jm-2 ] == 0 ) {
				tmp = X[ ix+2 ];
				X[ ix+2 ] = X[ iy-2 ];
				X[ iy-2 ] = tmp;
			}
			ix += 3;
			im += 3;
			iy -= 3;
			jm -= 3;
		}
		return;
	}
	iy = ix + ( (N-1) * strideX );
	jm = im + ( (N-1) * strideMask );
	for ( i = 0; i < n; i++ ) {
		if ( Mask[ im ] == 0 && Mask[ jm ] == 0 ) {
			tmp = X[ ix ];
			X[ ix ] = X[ iy ];
			X[ iy ] = tmp;
		}
		ix += strideX;
		im += strideMask;
		iy -= strideX;
		jm -= strideMask;
	}
	return;
}
